const fs = require('fs');
const path = require('path');

const ROOT = '/projects';
const HOST_ROOT = '/mnt/data/projects';
const OUTPUT_FILE = '/memory/project_structure.json';

const SKIP_DIRS = new Set(['.git', 'node_modules', 'venv', '.venv', '__pycache__', '.pytest_cache', 'dist', 'build', '.next', 'tmp', 'tmp_staging', 'credentials', 'site-packages', 'dist-packages', '.tox', '.mypy_cache', '.ruff_cache', '.eggs']);
const SKIP_DIR_SUFFIXES = ['.egg-info'];
const ALLOWED_EXT = new Set(['.py', '.js', '.jsx', '.ts', '.tsx', '.mjs', '.md', '.mdx', '.txt', '.json', '.yml', '.yaml', '.sh', '.toml', '.cfg', '.ini', '.html', '.css', '.scss', '.sql', '.lark', '.rst']);
const SKIP_FILE_NAMES = new Set(['package-lock.json', 'poetry.lock', 'uv.lock']);

function isSecret(name) {
  if (name === '.env.example') return false;
  if (name === '.env' || name.startsWith('.env.')) return true;
  if (name.endsWith('.pem') || name.endsWith('.key')) return true;
  if (name.startsWith('id_rsa')) return true;
  return false;
}

function isVenvRoot(dir) {
  try { return fs.existsSync(path.join(dir, 'pyvenv.cfg')); } catch (e) { return false; }
}

function buildTree(dir, hostDir, depth) {
  if (depth > 6) return null;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return null; }

  const node = {
    path: hostDir,
    directories: {},
    files: [],
    languages: {},
    file_count: 0
  };

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    const hostFull = path.join(hostDir, entry.name);
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      if (SKIP_DIR_SUFFIXES.some(function(s) { return entry.name.endsWith(s); })) continue;
      if (isVenvRoot(full)) continue;
      const child = buildTree(full, hostFull, depth + 1);
      if (child) {
        node.directories[entry.name] = child;
        node.file_count += child.file_count;
        for (const [lang, count] of Object.entries(child.languages)) {
          node.languages[lang] = (node.languages[lang] || 0) + count;
        }
      }
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name).toLowerCase();
      if (!ALLOWED_EXT.has(ext)) continue;
      if (SKIP_FILE_NAMES.has(entry.name)) continue;
      if (isSecret(entry.name)) continue;
      const lang = ext.slice(1) || 'unknown';
      node.files.push(entry.name);
      node.file_count++;
      node.languages[lang] = (node.languages[lang] || 0) + 1;
    }
  }

  return node;
}

let projectEntries;
try { projectEntries = fs.readdirSync(ROOT, { withFileTypes: true }); } catch (e) {
  return [{ json: { status: 'error', message: String(e) } }];
}

const structure = { generated_at: new Date().toISOString(), projects: {} };

for (const entry of projectEntries) {
  if (!entry.isDirectory()) continue;
  if (SKIP_DIRS.has(entry.name)) continue;
  const full = path.join(ROOT, entry.name);
  const hostFull = path.join(HOST_ROOT, entry.name);
  const tree = buildTree(full, hostFull, 1);
  if (tree) {
    structure.projects[entry.name] = {
      name: entry.name,
      host_path: hostFull,
      file_count: tree.file_count,
      languages: tree.languages,
      top_level_dirs: Object.keys(tree.directories),
      top_level_files: tree.files,
      tree: tree
    };
  }
}

fs.writeFileSync(OUTPUT_FILE, JSON.stringify(structure, null, 2));

return [{ json: {
  status: 'ok',
  projects: Object.keys(structure.projects),
  generated_at: structure.generated_at
} }];
